window.INSTRUCTION_CONTENT = {
  "sliders": {
    "title": "Smash Sliders Instructions",
    "heroTitle": "Smash<br><span>Sliders</span>",
    "heroSub": "Serves 3–4 · Prep ~30 min · Cook ~15 min",
    "body": "<!-- HERO -->\n<div class=\"hero\">\n  <div class=\"hero-title\">Smash<br><span>Sliders</span></div>\n  <div class=\"hero-sub\">Serves 3–4 · Prep ~30 min · Cook ~15 min</div>\n</div>\n\n<!-- ══ PHASE 1 ══ -->\n<div class=\"sec\">Do First</div>\n\n<div class=\"phase\">\n  <div class=\"phase-head\">\n    <div class=\"phase-num\">1</div>\n    <div class=\"phase-head-text\">\n      <span class=\"phase-label\">French Press · Stovetop</span>\n      <h3>Caramelized Onions</h3>\n    </div>\n    <div class=\"phase-time\">25–30 min</div>\n  </div>\n  <div class=\"phase-section\">\n    <ol class=\"steps\">\n      <li><span class=\"st\">Slice <span class=\"ing\">2 onions paper thin</span>.</span></li>\n      <li><span class=\"st\">Melt a generous knob of <span class=\"ing\">butter</span> in a pan on <span class=\"ing\">medium-low</span>.</span></li>\n      <li><span class=\"st\">Add onions and a pinch of salt. Stir occasionally. <span class=\"ing\">Do not rush or crank the heat.</span> They need the full time to get deep golden and jammy.</span></li>\n      <li><span class=\"st\">Once done, pull off heat and set aside. They'll stay warm on their own.</span></li>\n    </ol>\n  </div>\n</div>\n\n<!-- ══ PHASE 2 ══ -->\n<div class=\"sec\">While Onions Cook</div>\n\n<div class=\"phase\">\n  <div class=\"phase-head\">\n    <div class=\"phase-num\">2</div>\n    <div class=\"phase-head-text\">\n      <span class=\"phase-label\">All Sliders · Cold Prep</span>\n      <h3>Onions, Sauce & Cheese</h3>\n    </div>\n    <div class=\"phase-time\">10 min</div>\n  </div>\n  <div class=\"phase-section\">\n    <div class=\"phase-section-label\">Onions</div>\n    <ol class=\"steps\">\n      <li><span class=\"st\">Slice <span class=\"ing\">1 onion paper thin</span> for smashing into The Bad Boy patties. Set aside in a small pile.</span></li>\n      <li><span class=\"st\">Slice <span class=\"ing\">1 more onion paper thin</span> for the raw topping on The Motor City Closer. Keep in a separate pile.</span></li>\n    </ol>\n    <div class=\"phase-section-label\">Spicy Sauce</div>\n    <ol class=\"steps\">\n      <li><span class=\"st\">Mix <span class=\"ing\">3 tbsp mayo</span> + <span class=\"ing\">1.5 tbsp sriracha</span> + <span class=\"ing\">1 tsp yellow mustard</span> + <span class=\"ing\">splash of pickle juice</span>. Stir and set aside.</span></li>\n    </ol>\n    <div class=\"phase-section-label\">Cheese</div>\n    <ol class=\"steps\">\n      <li><span class=\"st\">Slice or shred <span class=\"ing\">Pepper Jack</span>, <span class=\"ing\">Gruyère</span>, and <span class=\"ing\">Sharp Cheddar</span> into three separate piles. Set near the flat top.</span></li>\n    </ol>\n  </div>\n</div>\n\n<!-- ══ PHASE 3 ══ -->\n<div class=\"sec\">Right Before Cooking</div>\n\n<div class=\"phase\">\n  <div class=\"phase-head\">\n    <div class=\"phase-num\">3</div>\n    <div class=\"phase-head-text\">\n      <span class=\"phase-label\">All Sliders · Final Prep</span>\n      <h3>Portion the Beef & Heat Up</h3>\n    </div>\n    <div class=\"phase-time\">5 min</div>\n  </div>\n  <div class=\"phase-section\">\n    <ol class=\"steps\">\n      <li><span class=\"st\">Loosely portion beef into <span class=\"ing\">1.5 oz balls</span> — roughly 12 total. Do not compress. Set on a tray.</span></li>\n      <li><span class=\"st\">Crank flat top to <span class=\"ing\">high</span> and let it fully preheat. A drop of water should instantly vaporize.</span></li>\n      <li><span class=\"st\">While flat top heats, butter the cut sides of the <span class=\"ing\">Hawaiian rolls</span> and have them ready to toast.</span></li>\n    </ol>\n  </div>\n</div>\n\n<!-- ══ PHASE 4 ══ -->\n<div class=\"sec\">Cook</div>\n\n<div class=\"phase\">\n  <div class=\"phase-head\">\n    <div class=\"phase-num\">4</div>\n    <div class=\"phase-head-text\">\n      <span class=\"phase-label\">Flat Top · All Sliders</span>\n      <h3>Toast the Buns</h3>\n    </div>\n  </div>\n  <div class=\"phase-section\">\n    <ol class=\"steps\">\n      <li><span class=\"st\">Drop flat top to <span class=\"ing\">medium-high</span>. Place rolls cut-side down. Toast <span class=\"ing\">1–2 min</span> until golden. Work in batches. Pull and set aside.</span></li>\n    </ol>\n  </div>\n</div>\n\n<div class=\"phase-gap\"></div>\n\n<div class=\"phase\">\n  <div class=\"phase-head\">\n    <div class=\"phase-num\">5</div>\n    <div class=\"phase-head-text\">\n      <span class=\"phase-label\">Slider 01 · Flat Top</span>\n      <h3>The Bad Boy</h3>\n    </div>\n  </div>\n  <div class=\"phase-section\">\n    <ol class=\"steps\">\n      <li><span class=\"st\">Crank flat top back to <span class=\"ing\">high</span>. Place 4 meat balls down with space between them.</span></li>\n      <li><span class=\"st\">Place a small pile of <span class=\"ing\">shaved onion</span> on top of each ball immediately.</span></li>\n      <li><span class=\"st\">Lay parchment over each ball. Smash hard within <span class=\"ing\">10 seconds</span>. Press and hold <span class=\"ing\">3–4 seconds</span>. Get them thin.</span></li>\n      <li><span class=\"st\">Season with salt and pepper. Cook <span class=\"ing\">90 sec – 2 min</span> without touching. Edges brown; top goes gray halfway up.</span></li>\n      <li><span class=\"st\">Scrape hard and fast, getting fully under the crust. Flip.</span></li>\n      <li><span class=\"st\">Lay <span class=\"ing\">Pepper Jack</span> on each patty. Splash water nearby, dome <span class=\"ing\">30–45 sec</span> to melt.</span></li>\n      <li><span class=\"st\">Build: <span class=\"ing\">spicy sauce</span> on both buns · patty · <span class=\"ing\">pickled jalapeños</span> on top.</span></li>\n    </ol>\n  </div>\n</div>\n\n<div class=\"phase-gap\"></div>\n\n<div class=\"phase\">\n  <div class=\"phase-head\">\n    <div class=\"phase-num\">6</div>\n    <div class=\"phase-head-text\">\n      <span class=\"phase-label\">Slider 02 · Flat Top</span>\n      <h3>The French Press</h3>\n    </div>\n  </div>\n  <div class=\"phase-section\">\n    <ol class=\"steps\">\n      <li><span class=\"st\">Same smash process as The Bad Boy — no onion on top before smashing.</span></li>\n      <li><span class=\"st\">Flip, add <span class=\"ing\">Gruyère</span>, dome to melt <span class=\"ing\">30–45 sec</span>.</span></li>\n      <li><span class=\"st\">Build: thin smear of <span class=\"ing\">Dijon</span> on bottom bun · thin smear of <span class=\"ing\">horseradish</span> · patty · big pile of <span class=\"ing\">caramelized onions</span> on top.</span></li>\n    </ol>\n  </div>\n</div>\n\n<div class=\"phase-gap\"></div>\n\n<div class=\"phase\">\n  <div class=\"phase-head\">\n    <div class=\"phase-num\">7</div>\n    <div class=\"phase-head-text\">\n      <span class=\"phase-label\">Slider 03 · Flat Top</span>\n      <h3>The Motor City Closer</h3>\n    </div>\n  </div>\n  <div class=\"phase-section\">\n    <ol class=\"steps\">\n      <li><span class=\"st\">Same smash process — no onion on top before smashing.</span></li>\n      <li><span class=\"st\">Flip, add <span class=\"ing\">Sharp Cheddar</span>, dome to melt <span class=\"ing\">30–45 sec</span>.</span></li>\n      <li><span class=\"st\">Build: <span class=\"ing\">yellow mustard</span> on bottom bun · patty · <span class=\"ing\">raw shaved onion</span> · <span class=\"ing\">dill pickle chips</span> on top.</span></li>\n    </ol>\n  </div>\n</div>\n\n<!-- TIMING BANNER -->\n<div class=\"timing\" style=\"margin-top:20px;\">\n  <div class=\"t-icon\">🔥</div>\n  <div>\n    <h4>Run All Three Back to Back</h4>\n    <p>Each batch takes about 3 minutes. Run Bad Boy first, French Press second, Closer last. Keep the flat top ripping hot between batches and don't let it sit cold.</p>\n  </div>\n</div>"
  },
  "honey-mustard": {
    "title": "Honey Mustard Chicken Instructions",
    "heroTitle": "HONEY<br><span>MUSTARD</span><br>NIGHT",
    "heroSub": "Serves 2–3 · Prep ~15 min · Cook ~45 min",
    "body": "<!-- HERO -->\n<div class=\"hero\">\n  <div class=\"hero-title\">HONEY<br><span>MUSTARD</span><br>NIGHT</div>\n  <div class=\"hero-sub\">Serves 2–3 · Prep ~15 min · Cook ~45 min</div>\n</div>\n\n<!-- LEGEND -->\n<div class=\"legend\">\n  <div class=\"legend-item\">\n    <div class=\"legend-dot\" style=\"background:#4a7abf;\"></div>\n    Jeff\n  </div>\n  <div class=\"legend-item\">\n    <div class=\"legend-dot\" style=\"background:#bf4a7a;\"></div>\n    Jaya\n  </div>\n  <div class=\"legend-item\">\n    <div class=\"legend-dot\" style=\"background:#c8850a;\"></div>\n    Theo\n  </div>\n</div>\n\n<!-- PREP -->\n<div class=\"sec\">Prep</div>\n\n<!-- JEFF: Preheat -->\n<div class=\"cook-block jeff\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#4a7abf;\"></div>\n    <div>\n      <span class=\"badge\">Jeff · First Thing</span>\n      <h3>Preheat the Oven</h3>\n    </div>\n    <div class=\"cook-emoji\">🌡️</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Turn oven to <span class=\"ing\">400°F</span>. Do this before anything else so it's fully up to temp by the time the potatoes are ready.</span></li>\n  </ol>\n</div>\n\n<!-- JAYA: Honey Mustard Glaze -->\n<div class=\"cook-block jaya\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#bf4a7a;\"></div>\n    <div>\n      <span class=\"badge\">Jaya · While Jeff Preps Potatoes</span>\n      <h3>Make the Glaze</h3>\n    </div>\n    <div class=\"cook-emoji\">🍯</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">In a small bowl whisk together <span class=\"ing\">3 tbsp Dijon</span>, <span class=\"ing\">3 tbsp yellow mustard</span>, <span class=\"ing\">4 tbsp honey</span>, and <span class=\"ing\">2 tbsp melted butter</span>. Season with salt and pepper.</span></li>\n    <li><span class=\"st\">Taste it. Should be sweet, tangy, and a little sharp. Adjust honey or mustard to your liking.</span></li>\n    <li><span class=\"st\">Split into <span class=\"ing\">two separate bowls</span> — one for cooking, one for the table as a dipping sauce. Once a bowl touches raw chicken it never goes on the table. Keep them separate from here.</span></li>\n  </ol>\n</div>\n\n<!-- THEO: Honey taste test -->\n<div class=\"cook-block theo\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#c8850a;\"></div>\n    <div>\n      <span class=\"badge\">Theo · Quality Control</span>\n      <h3>Honey Taste Test</h3>\n    </div>\n    <div class=\"cook-emoji\">🐾</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Let Theo lick a tiny bit of <span class=\"ing\">honey</span> off your finger. He has been present in the kitchen for 30 seconds and already considers himself the head chef. Besides, you were going to do it anyway.</span></li>\n  </ol>\n</div>\n\n<!-- JEFF: Prep Potatoes -->\n<div class=\"cook-block jeff\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#4a7abf;\"></div>\n    <div>\n      <span class=\"badge\">Jeff · Potatoes First</span>\n      <h3>Prep the Potatoes</h3>\n    </div>\n    <div class=\"cook-emoji\">🥔</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Wash the potatoes. Cut into roughly <span class=\"ing\">1-inch chunks</span> — no need to peel them.</span></li>\n    <li><span class=\"st\">In a large bowl toss with <span class=\"ing\">2 tbsp Dijon</span>, <span class=\"ing\">2 tbsp olive oil</span>, a generous pinch of <span class=\"ing\">salt</span>, and <span class=\"ing\">black pepper</span>.</span></li>\n    <li><span class=\"st\">Spread in a single layer on a sheet pan. Don't crowd them or they'll steam instead of crisp.</span></li>\n  </ol>\n</div>\n\n<!-- JAYA: Vinaigrette -->\n<div class=\"cook-block jaya\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#bf4a7a;\"></div>\n    <div>\n      <span class=\"badge\">Jaya · While Jeff Preps Chicken</span>\n      <h3>Make the Vinaigrette</h3>\n    </div>\n    <div class=\"cook-emoji\">🥗</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">In a small jar or bowl combine <span class=\"ing\">1 tsp Dijon</span>, <span class=\"ing\">3 tbsp olive oil</span>, <span class=\"ing\">1 tbsp apple cider vinegar</span>, salt and pepper.</span></li>\n    <li><span class=\"st\">Whisk or shake until emulsified. Taste and adjust — more vinegar for tang, more oil to mellow it out.</span></li>\n    <li><span class=\"st\">Set aside. Don't dress the greens until right before serving or they'll wilt.</span></li>\n  </ol>\n</div>\n\n<!-- JEFF: Prep Chicken -->\n<div class=\"cook-block jeff\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#4a7abf;\"></div>\n    <div>\n      <span class=\"badge\">Jeff · Chicken</span>\n      <h3>Prep the Chicken</h3>\n    </div>\n    <div class=\"cook-emoji\">🍗</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Pat chicken thighs dry with paper towels — key for getting a good crust without skin.</span></li>\n    <li><span class=\"st\">Season both sides generously with <span class=\"ing\">salt and pepper</span>.</span></li>\n    <li><span class=\"st\">Brush a <span class=\"ing\">light layer of glaze</span> from the cooking bowl over the top of each thigh. Just a thin coat — the heavy glaze goes on halfway through. This gets flavor in early without burning.</span></li>\n    <li><span class=\"st\">Place on a baking dish or sheet pan.</span></li>\n  </ol>\n</div>\n\n<!-- COOK -->\n<div class=\"sec\">Cook</div>\n\n<!-- JEFF: Roast -->\n<div class=\"cook-block jeff\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#4a7abf;\"></div>\n    <div>\n      <span class=\"badge\">Jeff · Oven · 400°F</span>\n      <h3>Roast Everything</h3>\n    </div>\n    <div class=\"cook-emoji\">🔥</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Put the <span class=\"ing\">potatoes</span> in the oven first. Set a timer for <span class=\"ing\">10 minutes</span>.</span></li>\n    <li><span class=\"st\">After 10 minutes, add the <span class=\"ing\">chicken</span> to the oven on a separate rack.</span></li>\n    <li><span class=\"st\">At the halfway point for the chicken (<span class=\"ing\">~15 min in</span>), flip the potatoes and brush a <span class=\"ing\">generous layer of glaze</span> from the cooking bowl over the chicken. This is when the caramelization happens — don't skip it.</span></li>\n    <li><span class=\"st\">Chicken is done when internal temp hits <span class=\"ing\">165°F</span> — boneless skinless thighs will be ready in roughly <span class=\"ing\">20–25 min</span>. Check early and don't let them go over or they'll dry out.</span></li>\n    <li><span class=\"st\">Potatoes are done when golden and crispy on the edges — roughly <span class=\"ing\">40–45 min</span> total. Soft inside, crispy outside.</span></li>\n  </ol>\n</div>\n\n<!-- THEO: Cooked chicken reward -->\n<div class=\"cook-block theo\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#c8850a;\"></div>\n    <div>\n      <span class=\"badge\">Theo · Well Earned</span>\n      <h3>Final Taste Test</h3>\n    </div>\n    <div class=\"cook-emoji\">🐾</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">While the chicken rests, pull off a small piece of <span class=\"ing\">plain cooked chicken</span> — no glaze, no seasoning — and give it to Theo. He has supervised this entire cook and his feedback has been invaluable.</span></li>\n    <li><span class=\"st\">Also give him a small plain <span class=\"ing\">cooked potato chunk</span>. He has been staring at them for 40 minutes. It's the right thing to do.</span></li>\n  </ol>\n</div>\n\n<!-- JAYA: Finish Salad -->\n<div class=\"cook-block jaya\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#bf4a7a;\"></div>\n    <div>\n      <span class=\"badge\">Jaya · While Chicken Rests</span>\n      <h3>Finish the Salad</h3>\n    </div>\n    <div class=\"cook-emoji\">🥗</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Once the chicken comes out of the oven, dress the <span class=\"ing\">greens</span> with the vinaigrette. Toss well and season with salt and pepper.</span></li>\n    <li><span class=\"st\">Serve immediately alongside the chicken and potatoes.</span></li>\n  </ol>\n</div>\n\n<!-- TIMING -->\n<div class=\"timing\" style=\"margin-top:20px;\">\n  <div class=\"t-icon\">⏱️</div>\n  <div>\n    <h4>Prep ~15 Min · Cook ~45 Min</h4>\n    <p>Potatoes go in first, chicken 10 minutes later. Boneless skinless thighs cook fast — check temp at 20 minutes. Heavy glaze goes on the chicken at the halfway mark. Two glaze bowls — cooking and table. Never mix them.</p>\n  </div>\n</div>"
  },
  "honey-garlic": {
    "title": "Honey Garlic Chicken Instructions",
    "heroTitle": "Honey Garlic Chicken Instructions",
    "heroSub": "",
    "body": "<div class=\"card\">\n\n  <!-- HERO -->\n  <div class=\"hero\">\n    <div class=\"recipe-label\">Tonight's Recipe</div>\n    <div class=\"recipe-title\">HONEY<br><span>GARLIC</span><br>CHICKEN</div>\n    <div class=\"recipe-meta\">\n      <div class=\"meta-item\">\n        <span class=\"meta-label\">Serves</span>\n        <span class=\"meta-value\">2–3</span>\n      </div>\n      <div class=\"meta-item\">\n        <span class=\"meta-label\">Prep</span>\n        <span class=\"meta-value\">~10 min</span>\n      </div>\n      <div class=\"meta-item\">\n        <span class=\"meta-label\">Cook</span>\n        <span class=\"meta-value\">~30 min</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- INGREDIENTS -->\n  <div class=\"ing-strip\">\n    <div class=\"ing-strip-title\">Ingredients</div>\n    <div class=\"ing-grid\">\n      <div class=\"ing-row\"><span class=\"ing-name\">Cucumber</span><span class=\"ing-qty\">½</span></div>\n      <div class=\"ing-row\"><span class=\"ing-name\">Chicken thighs</span><span class=\"ing-qty\">4–6</span></div>\n      <div class=\"ing-row\"><span class=\"ing-name\">Garlic cloves</span><span class=\"ing-qty\">6</span></div>\n      <div class=\"ing-row\"><span class=\"ing-name\">Green beans</span><span class=\"ing-qty\">2 handfuls</span></div>\n      <div class=\"ing-row\"><span class=\"ing-name\">Honey</span><span class=\"ing-qty\">3 tbsp</span></div>\n      <div class=\"ing-row\"><span class=\"ing-name\">Soy sauce</span><span class=\"ing-qty\">3 tbsp</span></div>\n      <div class=\"ing-row\"><span class=\"ing-name\">Chicken broth</span><span class=\"ing-qty\">½ cup</span></div>\n      <div class=\"ing-row\"><span class=\"ing-name\">Cornstarch</span><span class=\"ing-qty\">1 tbsp</span></div>\n      <div class=\"ing-row\"><span class=\"ing-name\">Butter</span><span class=\"ing-qty\">1 tbsp</span></div>\n      <div class=\"ing-row\"><span class=\"ing-name\">Olive oil</span><span class=\"ing-qty\">1 tbsp</span></div>\n    </div>\n  </div>\n\n  <!-- MAKE AHEAD -->\n  <div class=\"sec-header\">Make Ahead — Cucumber Bites</div>\n  <ol class=\"steps-list\">\n    <li class=\"step-item\">\n      <div class=\"step-num\">1</div>\n      <div class=\"step-text\">Slice <span class=\"ing\">cucumber</span> into rounds about <span class=\"ing\">¼ inch thick</span>. Arrange on a plate.</div>\n    </li>\n    <li class=\"step-item\">\n      <div class=\"step-num\">2</div>\n      <div class=\"step-text\">Drizzle with <span class=\"ing\">honey</span> and a small splash of <span class=\"ing\">soy sauce</span>. Sprinkle <span class=\"ing\">sesame seeds</span> if you have them. Cover and refrigerate until ready.</div>\n    </li>\n  </ol>\n\n  <!-- THEO 1 -->\n  <div class=\"theo-block\">\n    <div class=\"theo-icon\">🐾</div>\n    <div>\n      <span class=\"theo-label\">Theo — Act I · Hopeful</span>\n      <div class=\"theo-text\">Theo has smelled the honey and is now present. Give him a plain <span style=\"color:#c8102e;font-weight:700;\">cucumber round</span> — he's allowed. He will accept this graciously and immediately want another one.</div>\n    </div>\n  </div>\n\n  <!-- PREP -->\n  <div class=\"sec-header\">Prep</div>\n  <ol class=\"steps-list\">\n    <li class=\"step-item\">\n      <div class=\"step-num\">1</div>\n      <div class=\"step-text\">Mince <span class=\"ing\">6 garlic cloves</span>. This is a lot of garlic. That's correct. That's the dish.</div>\n    </li>\n    <li class=\"step-item\">\n      <div class=\"step-num\">2</div>\n      <div class=\"step-text\">Trim <span class=\"ing\">green beans</span>. If any are very long, cut them in half so they cook evenly. Set aside.</div>\n    </li>\n    <li class=\"step-item\">\n      <div class=\"step-num\">3</div>\n      <div class=\"step-text\">Whisk together <span class=\"ing\">3 tbsp honey</span>, <span class=\"ing\">3 tbsp soy sauce</span>, and <span class=\"ing\">½ cup chicken broth</span> in a small bowl. Set aside.</div>\n    </li>\n    <li class=\"step-item\">\n      <div class=\"step-num\">4</div>\n      <div class=\"step-text\">Mix <span class=\"ing\">1 tbsp cornstarch</span> with <span class=\"ing\">2 tbsp cold water</span> in a separate small bowl until smooth. Set aside.</div>\n    </li>\n    <li class=\"step-item\">\n      <div class=\"step-num\">5</div>\n      <div class=\"step-text\">Pat chicken thighs dry. Season both sides with <span class=\"ing\">salt and pepper</span>.</div>\n    </li>\n  </ol>\n\n  <div class=\"divider\">· · · ·</div>\n\n  <!-- RICE -->\n  <div class=\"sec-header\">Cook — Start the Rice First</div>\n  <ol class=\"steps-list\">\n    <li class=\"step-item\">\n      <div class=\"step-num\">1</div>\n      <div class=\"step-text\">Rinse <span class=\"ing\">rice</span> under cold water until mostly clear. Combine with water per package instructions in a pot. Bring to a boil, reduce to <span class=\"ing\">low</span>, cover, and cook <span class=\"ing\">18 minutes</span>. Do not lift the lid.</div>\n    </li>\n    <li class=\"step-item\">\n      <div class=\"step-num\">2</div>\n      <div class=\"step-text\">Once done, remove from heat and rest covered <span class=\"ing\">5 minutes</span>. It'll hold just fine while you finish the chicken.</div>\n    </li>\n  </ol>\n\n  <div class=\"divider\">· · · ·</div>\n\n  <!-- SEAR -->\n  <div class=\"sec-header\">Cook — Sear the Chicken</div>\n  <ol class=\"steps-list\">\n    <li class=\"step-item\">\n      <div class=\"step-num\">1</div>\n      <div class=\"step-text\">Heat <span class=\"ing\">olive oil</span> in a skillet over <span class=\"ing\">medium-high</span>. Sear chicken smooth-side down <span class=\"ing\">5–6 minutes</span> without touching until golden. Flip and cook another <span class=\"ing\">4 minutes</span>. Remove to a plate.</div>\n    </li>\n  </ol>\n\n  <!-- THEO 2 -->\n  <div class=\"theo-block\">\n    <div class=\"theo-icon\">😤</div>\n    <div>\n      <span class=\"theo-label\">Theo — Act II · Impatient</span>\n      <div class=\"theo-text\">The cucumber was not enough. He is aware something better is happening on the stove. He is pacing. He is not subtle about it.</div>\n    </div>\n  </div>\n\n  <!-- SAUCE -->\n  <div class=\"sec-header\">Cook — Build the Sauce</div>\n  <ol class=\"steps-list\">\n    <li class=\"step-item\">\n      <div class=\"step-num\">1</div>\n      <div class=\"step-text\">Drop heat to <span class=\"ing\">medium</span>. Add <span class=\"ing\">butter</span>. Add <span class=\"ing\">minced garlic</span> and cook <span class=\"ing\">1–2 minutes</span>, stirring constantly, until fragrant and just golden. Do not let it burn.</div>\n    </li>\n    <li class=\"step-item\">\n      <div class=\"step-num\">2</div>\n      <div class=\"step-text\">Pour in the <span class=\"ing\">honey soy broth mixture</span>. Bring to a simmer, scraping up any browned bits from the bottom.</div>\n    </li>\n    <li class=\"step-item\">\n      <div class=\"step-num\">3</div>\n      <div class=\"step-text\">Stir in the <span class=\"ing\">cornstarch slurry</span>. Sauce thickens quickly — keep stirring. Add a splash of water if it gets too thick.</div>\n    </li>\n    <li class=\"step-item\">\n      <div class=\"step-num\">4</div>\n      <div class=\"step-text\">Return <span class=\"ing\">chicken</span> to the pan with the <span class=\"ing\">green beans</span>. Spoon sauce over everything. Cover and simmer on <span class=\"ing\">low 5–7 minutes</span>, until chicken is cooked through and beans are tender-crisp.</div>\n    </li>\n  </ol>\n\n  <div class=\"divider\">· · · ·</div>\n\n  <!-- FINISH -->\n  <div class=\"sec-header\">Plate & Serve</div>\n  <ol class=\"steps-list\">\n    <li class=\"step-item\">\n      <div class=\"step-num\">1</div>\n      <div class=\"step-text\">Serve over <span class=\"ing\">rice</span>. Spoon extra sauce generously over everything — it's the best part.</div>\n    </li>\n    <li class=\"step-item\">\n      <div class=\"step-num\">2</div>\n      <div class=\"step-text\">Garnish with <span class=\"ing\">fresh parsley</span> if using.</div>\n    </li>\n  </ol>\n\n  <!-- THEO 3 -->\n  <div class=\"theo-block\">\n    <div class=\"theo-icon\">🐕</div>\n    <div>\n      <span class=\"theo-label\">Theo — Act III · The Payoff</span>\n      <div class=\"theo-text\">Give him a small piece of plain cooked chicken — no sauce. He has earned it. He will be very pleased with himself. All is forgiven.</div>\n    </div>\n  </div>\n\n  <!-- TIMING -->\n  <div class=\"timing-footer\">\n    <div class=\"icon\">⏱️</div>\n    <div>\n      <h4>Prep ~10 Min · Cook ~30 Min</h4>\n      <p>Start rice before you sear the chicken and everything lands together. The garlic step is the only one that needs your full attention — don't walk away from it.</p>\n    </div>\n  </div>\n\n  <div class=\"bottom-stamp\">Recipe Card No. 7 · Honey Garlic Chicken</div>\n\n</div>"
  },
  "meatloaf": {
    "title": "Meatloaf Instructions",
    "heroTitle": "MEAT<span>LOAF</span>",
    "heroSub": "Serves 4 · Prep ~25 min · Cook ~60 min",
    "body": "<!-- HERO -->\n<div class=\"hero\">\n  <div class=\"hero-title\">MEAT<span>LOAF</span></div>\n  <div class=\"hero-sub\">Serves 4 · Prep ~25 min · Cook ~60 min</div>\n</div>\n\n<!-- LEGEND -->\n<div class=\"legend\">\n  <div class=\"legend-item\">\n    <div class=\"legend-dot\" style=\"background:#4a7abf;\"></div>\n    Jeff\n  </div>\n  <div class=\"legend-item\">\n    <div class=\"legend-dot\" style=\"background:#bf4a7a;\"></div>\n    Jaya\n  </div>\n  <div class=\"legend-item\">\n    <div class=\"legend-dot\" style=\"background:#c8850a;\"></div>\n    Theo\n  </div>\n</div>\n\n<!-- PREP -->\n<div class=\"sec\">Prep</div>\n\n<!-- MEASUREMENTS REMINDER -->\n<div class=\"measure-banner\">\n  <div class=\"icon\">🥛</div>\n  <p><strong>A Note on Milk</strong>You need exactly <span style=\"font-weight:700;\">¼ cup</span>. Measure it into a measuring cup first. Do not pour from the carton directly. We've been here before.</p>\n</div>\n\n<!-- JEFF: Preheat -->\n<div class=\"cook-block jeff\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#4a7abf;\"></div>\n    <div>\n      <span class=\"badge\">Jeff · First Thing</span>\n      <h3>Preheat the Oven</h3>\n    </div>\n    <div class=\"cook-emoji\">🌡️</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Turn oven to <span class=\"ing\">350°F</span>. Lower and slower than the chicken — gives the meatloaf time to cook through evenly without drying out.</span></li>\n  </ol>\n</div>\n\n<!-- JAYA: Glaze -->\n<div class=\"cook-block jaya\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#bf4a7a;\"></div>\n    <div>\n      <span class=\"badge\">Jaya · Glaze</span>\n      <h3>Make the Glaze</h3>\n    </div>\n    <div class=\"cook-emoji\">🍯</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Whisk together <span class=\"ing\">1/3 cup ketchup</span>, <span class=\"ing\">1 tbsp Dijon</span>, <span class=\"ing\">1 tbsp brown sugar or honey</span>, <span class=\"ing\">1 tsp Worcestershire sauce</span>, <span class=\"ing\">1-2 tsp prepared horseradish</span>, and about <span class=\"ing\">¼ tsp black pepper</span>.</span></li>\n    <li><span class=\"st\">Set aside. You'll use half before the oven and half halfway through.</span></li>\n  </ol>\n</div>\n\n<!-- JEFF: Onion -->\n<div class=\"cook-block jeff\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#4a7abf;\"></div>\n    <div>\n      <span class=\"badge\">Jeff · Knife Work</span>\n      <h3>Soften the Onion</h3>\n    </div>\n    <div class=\"cook-emoji\">🔪</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Finely dice <span class=\"ing\">1 small yellow or white onion</span>.</span></li>\n    <li><span class=\"st\">Melt <span class=\"ing\">1 tbsp butter</span> in a small pan over medium-low. Add the onion and about <span class=\"ing\">⅛ tsp salt</span>. Cook <span class=\"ing\">6-8 minutes</span> until soft and translucent. Don't brown them.</span></li>\n    <li><span class=\"st\">Pull off heat and let cool for a few minutes before adding to the meat mixture.</span></li>\n  </ol>\n</div>\n\n<!-- JEFF: Mix -->\n<div class=\"cook-block jeff\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#4a7abf;\"></div>\n    <div>\n      <span class=\"badge\">Jeff · The Main Event</span>\n      <h3>Mix the Meatloaf</h3>\n    </div>\n    <div class=\"cook-emoji\">🥩</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">In a large bowl combine <span class=\"ing\">1.5 lbs ground beef</span>, <span class=\"ing\">1 large egg</span>, <span class=\"ing\">½ cup breadcrumbs</span>, and <span class=\"ing\">¼ cup milk</span> — measured, in a cup, not from the carton.</span></li>\n    <li><span class=\"st\">Before adding anything else — pinch off a <span class=\"ing\">2-inch chunk of plain beef</span>, mix in about <span class=\"ing\">1 tsp milk</span>, and roll it into a small ball. Set it aside on the corner of the sheet pan. This is Theo's Meatball. It goes in the oven with everything else, plain and safe.</span></li>\n    <li><span class=\"st\">Add <span class=\"ing\">1 tbsp Dijon</span>, <span class=\"ing\">2 tsp Worcestershire sauce</span>, <span class=\"ing\">1 tsp salt</span>, <span class=\"ing\">½ tsp black pepper</span>, <span class=\"ing\">½ tsp garlic powder</span>, and the <span class=\"ing\">cooled softened onion</span>.</span></li>\n    <li><span class=\"st\">Mix until just combined. <span class=\"ing\">Do not overmix</span> — work it too hard and it gets dense and tough. Stop as soon as everything is incorporated.</span></li>\n    <li><span class=\"st\">Transfer to a parchment-lined sheet pan and shape into a loaf roughly <span class=\"ing\">9 inches long</span> and <span class=\"ing\">4 inches wide</span>. Place Theo's Meatball on the corner of the same pan.</span></li>\n    <li><span class=\"st\">Brush the <span class=\"ing\">top only</span> with about <span class=\"ing\">2 tbsp glaze</span>. Not the sides — the beef will release fat as it bakes and wash it off anyway. The heavy glaze on the sides comes at the 40-minute mark.</span></li>\n  </ol>\n</div>\n\n<!-- COOK -->\n<div class=\"sec\">Cook</div>\n\n<!-- JEFF: Bake -->\n<div class=\"cook-block jeff\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#4a7abf;\"></div>\n    <div>\n      <span class=\"badge\">Jeff · Oven · 350°F</span>\n      <h3>Bake the Meatloaf</h3>\n    </div>\n    <div class=\"cook-emoji\">🔥</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Put the meatloaf in the oven. Set a timer for <span class=\"ing\">40 minutes</span>.</span></li>\n    <li><span class=\"st\">At 40 minutes, blot any large grease pools around the meatloaf with a paper towel. Then brush the remaining <span class=\"ing\">glaze generously over the top and sides</span> — the loaf has finished releasing most of its fat so the glaze will stick and caramelize now.</span></li>\n    <li><span class=\"st\">Pull <span class=\"ing\">Theo's Meatball</span> off the pan at this point — it's done. Set it aside to cool before giving it to him.</span></li>\n    <li><span class=\"st\">Continue baking another <span class=\"ing\">15–20 minutes</span> until the internal temp hits <span class=\"ing\">160°F</span>.</span></li>\n    <li><span class=\"st\">Pull from the oven and rest <span class=\"ing\">10 minutes</span> before slicing. Don't skip the rest — it holds together much better.</span></li>\n  </ol>\n</div>\n\n<!-- JAYA: Mashed Potatoes -->\n<div class=\"cook-block jaya\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#bf4a7a;\"></div>\n    <div>\n      <span class=\"badge\">Start When Meatloaf Goes In</span>\n      <h3>Green Onion Mashed Potatoes</h3>\n    </div>\n    <div class=\"cook-emoji\">🥔</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Peel and cut <span class=\"ing\">1.5 lbs potatoes</span> into rough chunks. Add to a pot, cover with cold water by about <span class=\"ing\">1 inch</span>, and add about <span class=\"ing\">1 tsp salt</span>. No need to turn the burner on yet — just get them ready.</span></li>\n    <li><span class=\"st\">When Jeff does the <span class=\"ing\">40-minute glaze check</span>, turn the burner on high and bring to a boil. This gives Jaya a relaxed runway — no rushing.</span></li>\n    <li><span class=\"st\">Boil <span class=\"ing\">15–18 minutes</span> until a fork slides in easily. Drain well.</span></li>\n    <li><span class=\"st\">Return to the pot. Add <span class=\"ing\">3 tbsp butter</span>, <span class=\"ing\">¼ cup warm milk</span>, about <span class=\"ing\">½ tsp salt</span>, and about <span class=\"ing\">¼ tsp black pepper</span>. Mash until smooth.</span></li>\n    <li><span class=\"st\">Fold in <span class=\"ing\">3 sliced green onions</span>. Hold on lowest heat until the meatloaf is rested and ready to slice.</span></li>\n  </ol>\n</div>\n\n<div class=\"cook-block jaya\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#bf4a7a;\"></div>\n    <div>\n      <span class=\"badge\">While Meatloaf Rests</span>\n      <h3>Garlic Butter Green Beans</h3>\n    </div>\n    <div class=\"cook-emoji\">🫘</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Trim <span class=\"ing\">12 oz green beans</span>. Melt <span class=\"ing\">1 tbsp butter</span> in a skillet over medium-high.</span></li>\n    <li><span class=\"st\">Add green beans with about <span class=\"ing\">¼ tsp salt</span>. Cook <span class=\"ing\">5-7 minutes</span>, tossing occasionally, until bright green and blistered in spots.</span></li>\n    <li><span class=\"st\">Add <span class=\"ing\">1 minced garlic clove</span> and cook <span class=\"ing\">30-60 seconds</span>. Finish with about <span class=\"ing\">⅛ tsp black pepper</span> and <span class=\"ing\">1 tsp lemon juice</span> if you have it.</span></li>\n  </ol>\n</div>\n\n<!-- THEO: Cooked Meatball -->\n<div class=\"cook-block theo\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\" style=\"background:#c8850a;\"></div>\n    <div>\n      <span class=\"badge\">Theo · His Moment</span>\n      <h3>The Theo Meatball</h3>\n    </div>\n    <div class=\"cook-emoji\">🐾</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Once Theo's Meatball has cooled down, give it to him. No glaze, no onion, no garlic — just plain beef, made specifically for him. He has been staring at the oven for 40 minutes and he has absolutely no idea any of this was for him. That's fine. He'll figure it out.</span></li>\n  </ol>\n</div>\n\n<!-- TIMING -->\n<div class=\"timing\" style=\"margin-top:20px;\">\n  <div class=\"t-icon\">⏱️</div>\n  <div>\n    <h4>Prep ~25 Min · Cook ~60 Min</h4>\n    <p>Prep potatoes when the meatloaf goes in, turn the burner on high at the 40-minute mark, and cook green beans while the meatloaf rests. Blot grease and glaze top and sides at 40 minutes. Theo's Meatball comes off the pan at that same check.</p>\n  </div>\n</div>"
  },
  "teriyaki": {
    "title": "Pineapple Orange Teriyaki Instructions",
    "heroTitle": "PINEAPPLE<br><span>TERIYAKI</span><br>SPREAD",
    "heroSub": "Serves 3 · Prep ~20 min · Cook ~30 min",
    "body": "<!-- HERO -->\n<div class=\"hero\">\n  <div class=\"hero-title\">PINEAPPLE<br><span>TERIYAKI</span><br>SPREAD</div>\n  <div class=\"hero-sub\">Serves 3 · Prep ~20 min · Cook ~30 min</div>\n</div>\n\n<!-- PREP -->\n<div class=\"sec\">Prep First</div>\n\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\"></div>\n    <div>\n      <span class=\"badge\">Do First</span>\n      <h3>Break Down the Pineapple</h3>\n    </div>\n    <div class=\"cook-emoji\">🍍</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Cut the top and bottom off the pineapple. Stand it upright and slice off the skin in strips from top to bottom. Remove any remaining eyes.</span></li>\n    <li><span class=\"st\">Cut into quarters lengthwise and remove the core from each quarter.</span></li>\n    <li><span class=\"st\">From one quarter, cut small bite-sized chunks for the <span class=\"ing\">cucumber bites</span>. Set aside.</span></li>\n    <li><span class=\"st\">From another quarter, cut slightly larger chunks for the <span class=\"ing\">finished teriyaki dish</span>. Set aside.</span></li>\n    <li><span class=\"st\">Squeeze or press the remaining pineapple over a bowl to collect <span class=\"ing\">pineapple juice</span> for the sauce — you need about <span class=\"ing\">3 tbsp</span>.</span></li>\n  </ol>\n</div>\n\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\"></div>\n    <div>\n      <span class=\"badge\">Make Ahead · Starter</span>\n      <h3>Cucumber Bites</h3>\n    </div>\n    <div class=\"cook-emoji\">🥒</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Slice the <span class=\"ing\">cucumber</span> into rounds about <span class=\"ing\">¼ inch thick</span>.</span></li>\n    <li><span class=\"st\">Top each round with a small piece of <span class=\"ing\">fresh pineapple</span>.</span></li>\n    <li><span class=\"st\">Drizzle lightly with <span class=\"ing\">honey</span> and add a small pinch of <span class=\"ing\">salt</span> over the whole tray.</span></li>\n    <li><span class=\"st\">Add a small <span class=\"ing\">mint leaf</span> on top of each if using. Cover and refrigerate until ready to serve. These can be made an hour ahead.</span></li>\n  </ol>\n</div>\n\n<!-- THEO -->\n<div class=\"cook-block theo\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\"></div>\n    <div>\n      <span class=\"badge\">Theo · Tropical Interest</span>\n      <h3>Pineapple Assessment</h3>\n    </div>\n    <div class=\"cook-emoji\">🐾</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Theo has never seen a pineapple this close before and is deeply suspicious of it. He may have a very small piece of plain pineapple — it's safe for dogs in small amounts. This will not satisfy him. Nothing satisfies him. Proceed.</span></li>\n  </ol>\n</div>\n\n<!-- RICE -->\n<div class=\"sec\">Coconut Rice</div>\n\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\"></div>\n    <div>\n      <span class=\"badge\">Start Before Chicken</span>\n      <h3>Coconut Rice</h3>\n    </div>\n    <div class=\"cook-emoji\">🍚</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Rinse <span class=\"ing\">1.5 cups jasmine rice</span> under cold water until the water runs mostly clear.</span></li>\n    <li><span class=\"st\">Combine in a pot with <span class=\"ing\">1 can coconut milk</span> plus enough water to bring the total liquid to <span class=\"ing\">2.25 cups</span>. Add <span class=\"ing\">½ tsp salt</span> and <span class=\"ing\">1 tsp sugar</span>.</span></li>\n    <li><span class=\"st\">Bring to a boil over medium-high, then reduce to <span class=\"ing\">low</span>, cover, and cook <span class=\"ing\">18 minutes</span>. Do not lift the lid.</span></li>\n    <li><span class=\"st\">Remove from heat and rest covered <span class=\"ing\">5 minutes</span>. Fluff with a fork. It will hold just fine while you finish the chicken.</span></li>\n  </ol>\n</div>\n\n<!-- CHICKEN -->\n<div class=\"sec\">Teriyaki Chicken</div>\n\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\"></div>\n    <div>\n      <span class=\"badge\">Mix the Sauce</span>\n      <h3>Teriyaki Sauce</h3>\n    </div>\n    <div class=\"cook-emoji\">🥢</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">In a small bowl whisk together <span class=\"ing\">¼ cup soy sauce</span>, <span class=\"ing\">3 tbsp honey</span>, <span class=\"ing\">3 tbsp pineapple juice</span>, <span class=\"ing\">juice of 1 orange</span>, <span class=\"ing\">3 garlic cloves minced</span>, and <span class=\"ing\">1 tsp fresh grated ginger</span>.</span></li>\n    <li><span class=\"st\">In a separate small bowl mix <span class=\"ing\">1 tbsp cornstarch</span> with <span class=\"ing\">2 tbsp cold water</span> until smooth. Set aside — this thickens the sauce at the end.</span></li>\n  </ol>\n</div>\n\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\"></div>\n    <div>\n      <span class=\"badge\">Main</span>\n      <h3>Sear & Sauce the Chicken</h3>\n    </div>\n    <div class=\"cook-emoji\">🍳</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Pat chicken thighs dry. Season both sides with <span class=\"ing\">salt and pepper</span>.</span></li>\n    <li><span class=\"st\">Heat <span class=\"ing\">1 tbsp oil</span> in a large skillet over <span class=\"ing\">medium-high</span>. Sear chicken smooth-side down <span class=\"ing\">5–6 minutes</span> without moving until golden. Flip and cook <span class=\"ing\">4 minutes</span> more. Remove to a plate — not fully cooked yet, that's fine.</span></li>\n    <li><span class=\"st\">Drop heat to <span class=\"ing\">medium</span>. Pour the <span class=\"ing\">teriyaki sauce</span> into the same pan and bring to a simmer, scraping up any browned bits.</span></li>\n    <li><span class=\"st\">Stir in the <span class=\"ing\">cornstarch slurry</span>. The sauce will thicken within a minute — stir constantly. If it gets too thick add a small splash of water.</span></li>\n    <li><span class=\"st\">Return the chicken to the pan. Add the <span class=\"ing\">pineapple chunks</span>. Spoon sauce over everything. Simmer on low <span class=\"ing\">5–6 minutes</span> until chicken is cooked through and sauce is glossy.</span></li>\n    <li><span class=\"st\">Garnish with <span class=\"ing\">sesame seeds</span> and <span class=\"ing\">sliced green onion</span> if using.</span></li>\n  </ol>\n</div>\n\n<!-- THEO FINAL -->\n<div class=\"cook-block theo\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\"></div>\n    <div>\n      <span class=\"badge\">Theo · Final Word</span>\n      <h3>Post-Cook Review</h3>\n    </div>\n    <div class=\"cook-emoji\">🐾</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Theo can have a small piece of plain <span class=\"ing\">cooked chicken</span> — no sauce, the soy and garlic make it off limits for him. He will look at the pineapple chunks and then back at you. Give him the chicken. Not the pineapple chunks. The chicken.</span></li>\n  </ol>\n</div>\n\n<!-- SERVE -->\n<div class=\"sec\">Serve</div>\n\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <div class=\"color-bar\"></div>\n    <div>\n      <span class=\"badge\">Plating</span>\n      <h3>Putting It Together</h3>\n    </div>\n    <div class=\"cook-emoji\">🍽️</div>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Put the <span class=\"ing\">cucumber bites</span> out first while you plate the main — they're the starter and keep people busy.</span></li>\n    <li><span class=\"st\">Spoon <span class=\"ing\">coconut rice</span> into bowls or onto plates. Lay the <span class=\"ing\">chicken</span> on top and spoon the <span class=\"ing\">teriyaki sauce and pineapple chunks</span> generously over everything.</span></li>\n    <li><span class=\"st\">Finish with <span class=\"ing\">sesame seeds</span> and <span class=\"ing\">green onion</span> if using. Serve immediately.</span></li>\n  </ol>\n</div>\n\n<!-- NOTE -->\n<div class=\"note-card\" style=\"margin-top:20px;\">\n  <h4>On the Sauce</h4>\n  <p>The cornstarch slurry thickens fast — have everything ready before you add it and keep stirring. If the sauce gets too thick before the chicken goes back in, add a small splash of water and stir.</p>\n</div>\n\n<!-- TIMING -->\n<div class=\"timing\" style=\"margin-top:14px;\">\n  <div class=\"t-icon\">⏱️</div>\n  <div>\n    <h4>Prep ~20 Min · Cook ~30 Min</h4>\n    <p>Make cucumber bites first — they sit in the fridge. Start rice before the chicken. Rice takes 23 minutes total, chicken about 20. Everything lands at the same time.</p>\n  </div>\n</div>"
  },
  "overnight-oats": {
    "title": "Overnight Oats Instructions",
    "heroTitle": "Overnight <span>Oats</span>",
    "heroSub": "Serves 5 · Prep ~10 min · Chill overnight",
    "body": "<div class=\"hero\">\n  <div class=\"hero-title\">Overnight <span>Oats</span></div>\n  <div class=\"hero-sub\">Serves 5 · Prep ~10 min · Chill overnight</div>\n</div>\n\n<div class=\"sec\">Prep</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Batch for the week</span>\n      <h3>Set up 5 jars</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Put out <span class=\"ing\">5 jars or containers</span> with lids.</span></li>\n    <li><span class=\"st\">Into each jar, add <span class=\"ing\">1/2 cup rolled oats</span>, <span class=\"ing\">1/2 cup Greek yogurt</span>, and <span class=\"ing\">1/2 cup milk</span>.</span></li>\n    <li><span class=\"st\">Add <span class=\"ing\">1 tsp chia seeds</span>, <span class=\"ing\">1 tsp honey or maple</span>, a small splash of vanilla, and a pinch of salt to each jar.</span></li>\n    <li><span class=\"st\">Stir each jar well, scraping the bottom so there are no dry oat pockets.</span></li>\n  </ol>\n</div>\n\n<div class=\"sec\">Flavor</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Keep it easy</span>\n      <h3>Make a few versions</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\"><span class=\"ing\">Berry vanilla:</span> add berries and a little extra vanilla.</span></li>\n    <li><span class=\"st\"><span class=\"ing\">Banana peanut butter:</span> add sliced banana and a spoonful of peanut butter.</span></li>\n    <li><span class=\"st\"><span class=\"ing\">Apple cinnamon:</span> add diced apple, cinnamon, and a small drizzle of honey.</span></li>\n    <li><span class=\"st\">If using granola or nuts, pack them separately so they stay crunchy.</span></li>\n  </ol>\n</div>\n\n<div class=\"sec\">Fridge</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">No morning work</span>\n      <h3>Chill and grab</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Lid the jars and refrigerate at least <span class=\"ing\">6 hours</span>, ideally overnight.</span></li>\n    <li><span class=\"st\">In the morning, grab a jar and go. Eat cold, straight from the container.</span></li>\n    <li><span class=\"st\">If a jar gets too thick, stir in a splash of milk before eating. For true grab-and-go, add that splash the night before.</span></li>\n    <li><span class=\"st\">Best texture is days <span class=\"ing\">1-4</span>. Day 5 is still fine, just softer.</span></li>\n  </ol>\n</div>"
  },
  "buffalo-chickpea-dip": {
    "title": "Buffalo Chickpea Dip Instructions",
    "heroTitle": "Buffalo <span>Chickpea Dip</span>",
    "heroSub": "Serves 4 · Prep ~10 min · Cook ~20 min",
    "body": "<div class=\"hero\">\n  <div class=\"hero-title\">Buffalo <span>Chickpea Dip</span></div>\n  <div class=\"hero-sub\">Serves 4 · Prep ~10 min · Cook ~20 min</div>\n</div>\n\n<div class=\"sec\">Pull Out</div>\n<div class=\"ingredient-pull\">\n  <div class=\"ingredient-pull-title\">Ingredients</div>\n  <div class=\"ingredient-pull-list\">\n    <span class=\"ingredient-pill\">Chickpeas</span>\n    <span class=\"ingredient-pill\">Plain hummus</span>\n    <span class=\"ingredient-pill\">Hot sauce</span>\n    <span class=\"ingredient-pill\">Green onions</span>\n    <span class=\"ingredient-pill\">Fresh garlic</span>\n    <span class=\"ingredient-pill\">Smoked paprika</span>\n    <span class=\"ingredient-pill\">Cayenne</span>\n    <span class=\"ingredient-pill\">Olive oil</span>\n    <span class=\"ingredient-pill\">Shredded cheese</span>\n    <span class=\"ingredient-pill\">Pita</span>\n    <span class=\"ingredient-pill\">Lemon</span>\n    <span class=\"ingredient-pill\">Small baking dish</span>\n  </div>\n</div>\n\n<div class=\"sec\">Make Dip</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Mild base, optional heat</span>\n      <h3>Build the base</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Heat oven to <span class=\"ing\">400 F</span>. Drain and rinse <span class=\"ing\">1 can chickpeas</span>.</span></li>\n    <li><span class=\"st\">Mash about two-thirds of the chickpeas in a bowl. Keep the last third mostly whole.</span></li>\n    <li><span class=\"st\">Stir in the whole chickpeas, <span class=\"ing\">1/2 cup plain hummus</span>, <span class=\"ing\">2 tbsp buffalo-style hot sauce</span>, <span class=\"ing\">2 tsp olive oil</span>, <span class=\"ing\">1 small grated garlic clove</span>, and <span class=\"ing\">1/4 tsp smoked paprika</span>.</span></li>\n    <li><span class=\"st\">For a medium batch: add another <span class=\"ing\">2 tbsp buffalo-style hot sauce</span> and <span class=\"ing\">1/8 tsp cayenne</span>. Skip this step for a mild batch.</span></li>\n  </ol>\n</div>\n\n<div class=\"sec\">Bake</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Warm and scoopable</span>\n      <h3>Finish it</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Spread into a small baking dish. Sprinkle on a small handful of <span class=\"ing\">shredded cheese</span> if using. Drizzle a little extra hot sauce over the top only if you are making the medium version.</span></li>\n    <li><span class=\"st\">Bake <span class=\"ing\">15-18 minutes</span>, until hot at the edges and thick enough to scoop.</span></li>\n    <li><span class=\"st\">If the top looks pale, broil for <span class=\"ing\">1-2 minutes</span>, watching closely.</span></li>\n    <li><span class=\"st\">Top with sliced green onions. Add a squeeze of lemon only if it needs brightness at the end.</span></li>\n  </ol>\n</div>\n\n<div class=\"sec\">Pita Chips</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Use the pitas you already bought</span>\n      <h3>Make scoops</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Cut pita into sturdy wedges. Brush or toss lightly with about <span class=\"ing\">1 tbsp olive oil per 2 pitas</span>.</span></li>\n    <li><span class=\"st\">Season with a little <span class=\"ing\">salt</span>, plus garlic powder or smoked paprika if you want.</span></li>\n    <li><span class=\"st\">Bake at <span class=\"ing\">400 F</span> for <span class=\"ing\">6-10 minutes</span>, flipping once, until crisp at the edges.</span></li>\n    <li><span class=\"st\">Let them cool for a few minutes so they firm up before scooping the dip.</span></li>\n  </ol>\n</div>"
  },
  "chicken-skewers": {
    "title": "Chicken Skewers Instructions",
    "heroTitle": "Chicken <span>Skewers</span>",
    "heroSub": "Serves 2–3 · Prep ~25 min · Cook ~35 min",
    "body": "<div class=\"hero\">\n  <div class=\"hero-title\">Chicken <span>Skewers</span></div>\n  <div class=\"hero-sub\">Serves 2–3 · Prep ~25 min · Cook ~35 min</div>\n</div>\n\n<div class=\"sec\">Drink</div>\n<div class=\"ingredient-pull\">\n  <div class=\"ingredient-pull-title\">Pull Out</div>\n  <div class=\"ingredient-pull-list\">\n    <span class=\"ingredient-pill\">Gin</span>\n    <span class=\"ingredient-pill\">Soda water</span>\n    <span class=\"ingredient-pill\">Cucumber</span>\n    <span class=\"ingredient-pill\">Lemon</span>\n    <span class=\"ingredient-pill\">Honey</span>\n    <span class=\"ingredient-pill\">Ice</span>\n  </div>\n</div>\n<div class=\"cook-block wide-half\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Cold and bright</span>\n      <h3>Cucumber gin highball</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">If using honey, loosen it first: stir <span class=\"ing\">1 part honey</span> with <span class=\"ing\">1 part warm water</span> to make a quick honey syrup. Use <span class=\"ing\">1 tsp honey syrup</span> per drink, or swap in simple syrup.</span></li>\n    <li><span class=\"st\">In a glass, stir <span class=\"ing\">2 oz gin</span>, <span class=\"ing\">1/2 oz lemon juice</span>, and the honey syrup until combined.</span></li>\n    <li><span class=\"st\">Add ice and a few thin <span class=\"ing\">cucumber slices</span>. Top with <span class=\"ing\">soda water</span>.</span></li>\n    <li><span class=\"st\">Give it one gentle stir. Taste and add a little more lemon or syrup if you want it sharper or softer.</span></li>\n  </ol>\n</div>\n\n<div class=\"sec\">Prep First</div>\n<div class=\"ingredient-pull\">\n  <div class=\"ingredient-pull-title\">Pull Out</div>\n  <div class=\"ingredient-pull-list\">\n    <span class=\"ingredient-pill\">Chicken thighs</span>\n    <span class=\"ingredient-pill\">Skewers</span>\n    <span class=\"ingredient-pill\">Pita</span>\n    <span class=\"ingredient-pill\">Lemons</span>\n    <span class=\"ingredient-pill\">Garlic</span>\n    <span class=\"ingredient-pill\">Olive oil</span>\n    <span class=\"ingredient-pill\">Paprika</span>\n    <span class=\"ingredient-pill\">Oregano</span>\n    <span class=\"ingredient-pill\">Dijon</span>\n    <span class=\"ingredient-pill\">Salt & pepper</span>\n  </div>\n</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Before lighting</span>\n      <h3>Marinate and organize</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">If using wooden skewers, soak them in water for <span class=\"ing\">30 minutes</span> so they do not scorch immediately.</span></li>\n    <li><span class=\"st\">Cut chicken thighs into 1 1/2 inch pieces. Toss with <span class=\"ing\">2 tbsp olive oil</span>, lemon zest, lemon juice, grated garlic, <span class=\"ing\">1 tsp kosher salt</span>, pepper, smoked paprika, oregano, and <span class=\"ing\">1 tsp Dijon</span>.</span></li>\n    <li><span class=\"st\">Thread chicken onto skewers with a tiny bit of space between pieces. Crowded skewers steam instead of grill.</span></li>\n  </ol>\n</div>\n\n<div class=\"sec\">Light Charcoal</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Start before the sides</span>\n      <h3>Get the chimney going</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Open the bottom vent and lid vent all the way. Charcoal heat is controlled by air: more open means hotter, more closed means cooler.</span></li>\n    <li><span class=\"st\">Set the chimney starter on the charcoal grate, not on a table, deck, or plastic surface.</span></li>\n    <li><span class=\"st\">Put <span class=\"ing\">1 lighter cube</span> under the chimney. Fill the chimney about <span class=\"ing\">2/3 full</span> for this cook. Skip lighter fluid.</span></li>\n    <li><span class=\"st\">Light the cube through a lower chimney hole. Leave it alone for <span class=\"ing\">15-20 minutes</span> while the fire climbs upward.</span></li>\n    <li><span class=\"st\">The coals are ready when the top pieces are gray around the edges and you can see orange glow down in the chimney. If the top is still mostly black, wait.</span></li>\n  </ol>\n</div>\n\n<div class=\"sec\">Sauce</div>\n<div class=\"ingredient-pull\">\n  <div class=\"ingredient-pull-title\">Pull Out</div>\n  <div class=\"ingredient-pull-list\">\n    <span class=\"ingredient-pill\">Chicken broth</span>\n    <span class=\"ingredient-pill\">Greek yogurt</span>\n    <span class=\"ingredient-pill\">Horseradish</span>\n    <span class=\"ingredient-pill\">Honey</span>\n    <span class=\"ingredient-pill\">Dijon</span>\n    <span class=\"ingredient-pill\">Lemon</span>\n    <span class=\"ingredient-pill\">Pepper</span>\n  </div>\n</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Make while coals light</span>\n      <h3>Creamy dipping sauce</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Simmer <span class=\"ing\">1 cup chicken broth</span> with <span class=\"ing\">1 tbsp Dijon</span>, <span class=\"ing\">1 tsp honey</span>, and a squeeze of lemon until reduced by about a third.</span></li>\n    <li><span class=\"st\">Cool for a minute. Whisk in <span class=\"ing\">1/3 cup Greek yogurt or sour cream</span> and <span class=\"ing\">1-2 tbsp horseradish</span>. Season with pepper and more lemon.</span></li>\n    <li><span class=\"st\">Keep warm but do not boil after the dairy goes in. Serve as a dip for chicken and pita.</span></li>\n  </ol>\n</div>\n\n<div class=\"sec\">Cold Side</div>\n<div class=\"ingredient-pull\">\n  <div class=\"ingredient-pull-title\">Pull Out</div>\n  <div class=\"ingredient-pull-list\">\n    <span class=\"ingredient-pill\">Cucumber</span>\n    <span class=\"ingredient-pill\">Tomatoes</span>\n    <span class=\"ingredient-pill\">Parsley</span>\n    <span class=\"ingredient-pill\">Lemon</span>\n    <span class=\"ingredient-pill\">Olive oil</span>\n    <span class=\"ingredient-pill\">Salt & pepper</span>\n  </div>\n</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Also while coals light</span>\n      <h3>Cucumber tomato salad</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Slice cucumber, halve tomatoes, and thinly slice a little red onion if using.</span></li>\n    <li><span class=\"st\">Toss with about <span class=\"ing\">1 tbsp olive oil</span>, <span class=\"ing\">1 tbsp lemon juice</span>, parsley, salt, and pepper.</span></li>\n    <li><span class=\"st\">Set aside until the skewers and pita are done.</span></li>\n  </ol>\n</div>\n\n<div class=\"sec\">Build Fire</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Two-zone setup</span>\n      <h3>Hot side and safe side</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Carefully pour the lit coals onto <span class=\"ing\">one side</span> of the grill. Leave the other side mostly empty.</span></li>\n    <li><span class=\"st\">Put the cooking grate on, close the lid, and let the grill run hot for <span class=\"ing\">10-15 minutes</span> to burn off old buildup.</span></li>\n    <li><span class=\"st\">Scrape the hot grate hard with a grill brush or a ball of foil held in tongs.</span></li>\n    <li><span class=\"st\">Oil the grate lightly with a folded paper towel held in tongs. Do not soak it so much that oil drips into the coals.</span></li>\n    <li><span class=\"st\">Put the lid vent over the cooler side so heat and smoke travel across the food instead of straight out.</span></li>\n  </ol>\n</div>\n\n<div class=\"sec\">Grill</div>\n<div class=\"ingredient-pull\">\n  <div class=\"ingredient-pull-title\">Pull Out</div>\n  <div class=\"ingredient-pull-list\">\n    <span class=\"ingredient-pill\">Skewers</span>\n    <span class=\"ingredient-pill\">Pita</span>\n  </div>\n</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Skewers cook fast</span>\n      <h3>Chicken and pita</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Start skewers over direct heat. Grill with the lid open, turning every 2-3 minutes, until the outside has good color.</span></li>\n    <li><span class=\"st\">If the chicken is browning too fast or dripping causes flare-ups, slide skewers to the cooler side and close the lid.</span></li>\n    <li><span class=\"st\">Cook chicken to <span class=\"ing\">165 F</span>. Thigh pieces usually take <span class=\"ing\">10-14 minutes</span> total depending on heat.</span></li>\n    <li><span class=\"st\">Warm pita for <span class=\"ing\">30-60 seconds per side</span> at the end. Watch closely; bread burns fast over charcoal.</span></li>\n  </ol>\n</div>\n\n<div class=\"sec\">Dessert</div>\n<div class=\"ingredient-pull\">\n  <div class=\"ingredient-pull-title\">Pull Out</div>\n  <div class=\"ingredient-pull-list\">\n    <span class=\"ingredient-pill\">Extra pita</span>\n    <span class=\"ingredient-pill\">Greek yogurt</span>\n    <span class=\"ingredient-pill\">Honey</span>\n    <span class=\"ingredient-pill\">Cinnamon</span>\n    <span class=\"ingredient-pill\">Vanilla</span>\n    <span class=\"ingredient-pill\">Salt</span>\n  </div>\n</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Use the last heat</span>\n      <h3>Honey-cinnamon pita chips</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Cut extra pita or naan into wedges. Brush lightly with about <span class=\"ing\">1 tsp olive oil</span> and sprinkle with <span class=\"ing\">cinnamon</span> and a tiny pinch of salt.</span></li>\n    <li><span class=\"st\">Grill over the cooler side for <span class=\"ing\">30-60 seconds per side</span>, just until warm, crisp at the edges, and lightly marked. Watch closely; they go fast.</span></li>\n    <li><span class=\"st\">Stir <span class=\"ing\">Greek yogurt</span> with <span class=\"ing\">honey</span>, a splash of vanilla, and a pinch of cinnamon.</span></li>\n    <li><span class=\"st\">Serve the warm pita chips with the honey yogurt dip.</span></li>\n  </ol>\n</div>\n\n<div class=\"sec\">Shut Down</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">After eating</span>\n      <h3>Close the vents</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Close the bottom vent and lid vent all the way to starve the coals of oxygen.</span></li>\n    <li><span class=\"st\">Leave ash and spent coals in the grill until fully cool. Empty them later into a metal ash bucket or lidded metal container.</span></li>\n  </ol>\n</div>"
  },
  "carnitas-elote-bowls": {
    "title": "Carnitas Elote Bowls Instructions",
    "heroTitle": "Carnitas <span>Elote Bowls</span>",
    "heroSub": "Serves 2-3 · Prep ~15 min · Cook ~25 min",
    "body": "<div class=\"hero\">\n  <div class=\"hero-title\">Carnitas <span>Elote Bowls</span></div>\n  <div class=\"hero-sub\">Serves 2-3 · Prep ~15 min · Cook ~25 min</div>\n</div>\n\n<div class=\"sec\">Drink</div>\n<div class=\"ingredient-pull\">\n  <div class=\"ingredient-pull-title\">Pull Out</div>\n  <div class=\"ingredient-pull-list\">\n    <span class=\"ingredient-pill\">Tequila</span>\n    <span class=\"ingredient-pill\">Lime</span>\n    <span class=\"ingredient-pill\">Soda water</span>\n    <span class=\"ingredient-pill\">Salt</span>\n    <span class=\"ingredient-pill\">Ice</span>\n  </div>\n</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Bright and easy</span>\n      <h3>Charred lime ranch water</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">If you want the charred lime thing, put <span class=\"ing\">1 lime half</span> cut-side down in a dry hot skillet for <span class=\"ing\">2-3 minutes</span>, until deeply browned. Regular fresh lime is also totally fine.</span></li>\n    <li><span class=\"st\">Fill a glass with <span class=\"ing\">ice</span>. Add <span class=\"ing\">2 oz tequila</span>, <span class=\"ing\">1 oz lime juice</span>, and a tiny pinch of <span class=\"ing\">salt</span>.</span></li>\n    <li><span class=\"st\">Top with cold <span class=\"ing\">soda water</span> or sparkling mineral water. Stir once and taste. Add more lime if it needs to snap.</span></li>\n  </ol>\n</div>\n\n<div class=\"sec\">Start Rice</div>\n<div class=\"ingredient-pull\">\n  <div class=\"ingredient-pull-title\">Pull Out</div>\n  <div class=\"ingredient-pull-list\">\n    <span class=\"ingredient-pill\">Rice</span>\n    <span class=\"ingredient-pill\">Lime</span>\n    <span class=\"ingredient-pill\">Cilantro</span>\n    <span class=\"ingredient-pill\">Butter or oil</span>\n    <span class=\"ingredient-pill\">Salt</span>\n  </div>\n</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Base layer</span>\n      <h3>Cilantro lime rice</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Cook <span class=\"ing\">1 cup dry white rice</span> according to the package with a pinch of <span class=\"ing\">salt</span>.</span></li>\n    <li><span class=\"st\">When rice is done, fluff with <span class=\"ing\">1 tbsp butter or oil</span>, <span class=\"ing\">1 tbsp lime juice</span>, and <span class=\"ing\">2 tbsp chopped cilantro</span>.</span></li>\n    <li><span class=\"st\">Keep covered off heat while you make the toppings.</span></li>\n  </ol>\n</div>\n\n<div class=\"sec\">Elote</div>\n<div class=\"ingredient-pull\">\n  <div class=\"ingredient-pull-title\">Pull Out</div>\n  <div class=\"ingredient-pull-list\">\n    <span class=\"ingredient-pill\">Corn</span>\n    <span class=\"ingredient-pill\">Mayo</span>\n    <span class=\"ingredient-pill\">Sour cream</span>\n    <span class=\"ingredient-pill\">Cotija</span>\n    <span class=\"ingredient-pill\">Green onions</span>\n    <span class=\"ingredient-pill\">Lime</span>\n    <span class=\"ingredient-pill\">Chili powder</span>\n    <span class=\"ingredient-pill\">White onion</span>\n  </div>\n</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Creamy corn topping</span>\n      <h3>Make the elote corn</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Heat <span class=\"ing\">2 cups corn</span> in a dry skillet over medium-high for <span class=\"ing\">5-7 minutes</span>, stirring occasionally, until hot and a little browned in spots.</span></li>\n    <li><span class=\"st\">Move corn to a bowl. Stir in <span class=\"ing\">2 tbsp mayo</span>, <span class=\"ing\">2 tbsp sour cream or crema</span>, <span class=\"ing\">1/2 cup cotija</span>, <span class=\"ing\">2 sliced green onions</span>, <span class=\"ing\">1 tbsp lime juice</span>, and <span class=\"ing\">1/2 tsp chili powder</span>.</span></li>\n    <li><span class=\"st\">Taste and add a pinch of salt or more lime if it tastes flat.</span></li>\n    <li><span class=\"st\">If using <span class=\"ing\">white onion</span>, finely dice <span class=\"ing\">1-2 tbsp</span> and toss with a squeeze of <span class=\"ing\">lime</span> and a tiny pinch of salt. Let it sit until assembly so it softens into a sharp little topping.</span></li>\n  </ol>\n</div>\n\n<div class=\"sec\">Carnitas</div>\n<div class=\"ingredient-pull\">\n  <div class=\"ingredient-pull-title\">Pull Out</div>\n  <div class=\"ingredient-pull-list\">\n    <span class=\"ingredient-pill\">Carnitas</span>\n    <span class=\"ingredient-pill\">Oil</span>\n    <span class=\"ingredient-pill\">Lime</span>\n  </div>\n</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Heat and crisp</span>\n      <h3>Crisp the carnitas</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Heat a skillet over medium-high with a thin layer of <span class=\"ing\">oil</span>, about <span class=\"ing\">1 tsp</span>.</span></li>\n    <li><span class=\"st\">Add <span class=\"ing\">2-3 cups carnitas</span> in a loose layer. Let it sit untouched for <span class=\"ing\">2-3 minutes</span> so the edges crisp.</span></li>\n    <li><span class=\"st\">Flip and crisp another <span class=\"ing\">2-3 minutes</span>. Finish with a squeeze of <span class=\"ing\">lime</span>.</span></li>\n  </ol>\n</div>\n\n<div class=\"sec\">Bowls</div>\n<div class=\"ingredient-pull\">\n  <div class=\"ingredient-pull-title\">Pull Out</div>\n  <div class=\"ingredient-pull-list\">\n    <span class=\"ingredient-pill\">Avocado</span>\n    <span class=\"ingredient-pill\">Cabbage</span>\n    <span class=\"ingredient-pill\">Cilantro</span>\n    <span class=\"ingredient-pill\">Hot sauce</span>\n    <span class=\"ingredient-pill\">Tortilla chips</span>\n    <span class=\"ingredient-pill\">Lime-pickled onion</span>\n  </div>\n</div>\n<div class=\"cook-block\">\n  <div class=\"cook-head\">\n    <span>\n      <span class=\"badge\">Build with contrast</span>\n      <h3>Assemble and finish</h3>\n    </span>\n  </div>\n  <ol class=\"cook-steps\">\n    <li><span class=\"st\">Add rice to bowls, then pile on crispy carnitas and a big spoonful of elote corn.</span></li>\n    <li><span class=\"st\">Top with sliced <span class=\"ing\">avocado</span>, a handful of <span class=\"ing\">shredded cabbage</span>, the <span class=\"ing\">lime-pickled white onion</span> if using, extra <span class=\"ing\">cilantro</span>, and <span class=\"ing\">hot sauce</span>.</span></li>\n    <li><span class=\"st\">Crush a few <span class=\"ing\">tortilla chips</span> over the top if you want crunch. Serve with extra lime wedges.</span></li>\n  </ol>\n</div>"
  }
};

